/* 0x0202e1f0 (0x178 bytes) Game_unlinkEntity (Ghidra: Sound_play)
 * file: name */
/* Takes ent off its tile's list (its ambient sound stops) */
void Game_unlinkEntity( Game *self, Entity *ent ) {
	int tile = ent->tile;

	Dbg_printf( "unlinking %i from %d %d", ent->def->name, tile % MAP_TILES, tile / MAP_TILES );
	if ( ent == &self->entities[0] ) {
		App_fatal( app, "unlinkEntity: attempt to unlink world with wrong routine" );
		return;
	}
	if ( !ent->next && !ent->prev && self->tileLists[ent->tile] != ent ) {
		Dbg_printf( "unlinkEntity: attempt to unlink non-linked entity %i (%d) at %d %d", ent->def->name,
			(int)( ent - self->entities ), ent->tile % MAP_TILES, ent->tile / MAP_TILES );
	}
	if ( self->tileLists[ent->tile] == ent ) {
		self->tileLists[ent->tile] = ent->next;
	} else if ( ent->prev ) {
		ent->prev->next = ent->next;
	}
	if ( ent->next ) {
		ent->next->prev = ent->prev;
	}
	ent->next = NULL;
	ent->prev = NULL;
	ent->info &= ~ENT_LINKED;
	if ( ent->emitter != 0xff ) {
		Sound_setEmitter( self->app->sound, ent->emitter, 0 );
	}
	Automap_tileChanged( self->app->menuSystem, ent->tile % MAP_TILES, ent->tile / MAP_TILES );
}

/* 0x0202e368 (0x20c bytes) Game_linkEntity (Ghidra: FUN_0202e368)
 * file: name */
/* Puts ent on the list of tile tx, ty. Items (eType 5) go before the first world or item entity
 * (the props and monsters stay in front of them); the rest go first. An entity with an ambient
 * sound turns it on there (a fire, eType 15, only if its parameter has 0x100). */
void Game_linkEntity( Game *self, Entity *ent, int tx, int ty ) {
	Entity	*head, *prev, *cur;
	int		tile;

	Dbg_printf( "linking %i to %d %d", ent->def->name, tx, ty );
	if ( ent == &self->entities[0] ) {
		App_fatal( app, "linkEntity: attempt to link world into list" );
		return;
	}
	tile = tx + ty * MAP_TILES;
	if ( ent->next || ent->prev || self->tileLists[tile] == ent ) {
		App_fatal( app, "linkEntity: attempt to link linked entity %i (%d) at %d %d", ent->def->name,
			(int)( ent - self->entities ), tx, ty );
		return;
	}
	tile = (s16)tile;
	head = self->tileLists[tile];
	if ( ent->def->eType == 5 ) {
		prev = NULL;
		cur = head;
		while ( cur && cur->def->eType != 0 && cur->def->eType != 5 ) {
			prev = cur;
			cur = cur->next;
		}
		if ( prev ) {
			prev->next = ent;
		} else {
			self->tileLists[tile] = ent;
		}
		ent->prev = prev;
		ent->next = cur;		/* (cur->prev is left as it was) */
	} else {
		ent->next = head;
		if ( head ) {
			head->prev = ent;
		}
		ent->prev = NULL;
		self->tileLists[tile] = ent;
	}
	ent->tile = (s16)tile;
	ent->info |= ENT_LINKED;
	if ( ent->emitter != 0xff ) {
		if ( ent->def->eType == 0xf ) {
			Sound_setEmitter( self->app->sound, ent->emitter, ( ent->param & 0x100 ) != 0 );
		} else {
			Sound_setEmitter( self->app->sound, ent->emitter, 1 );
		}
		Sound_moveEmitter( self->app->sound, ent->emitter, TILE_CENTER( tx ), TILE_CENTER( ty ) );
	}
	Automap_tileChanged( self->app->menuSystem, tx, ty );
}

