/* The player touches what lies on the tile of x, y: fires (eType 8) only, or all with force */
int Game_touchTile( Game *self, int x, int y, int force ) {
	Entity	*e, *next;
	int		touched = 0;

	for ( e = Game_getTileEntities( self, x, y ); e; e = next ) {
		next = e->next;
		if ( force || e->def->eType == 8 ) {
			Game_touchEntity( self, e );
			touched = 1;
		}
	}
	return touched;
}

