/* A monster becomes active: off the inactive ring, onto the active one (where the AI moves it).
 * distCheck: only within about 4.8 tiles of the view. alert: a monster that has an event on its tile
 * (monster flag 0x10) runs it. A visible monster that has an alert sound is picked to make it (one
 * of several at random). */
void Game_activateEx( Game *self, Entity *ent, int alert, int distCheck ) {
	Monster *m = ent->monster;

	if ( distCheck && Entity_distSqFrom( ent, self->canvas->viewX, self->canvas->viewY ) > 0x24000 ) {
		return;
	}
	ent->info |= ENT_DIRTY;
	if ( self->player->noTarget ) {
		return;
	}
	if ( ent->def->eSubType == 2 ) {
		if ( !( ent->info & ENT_AGGRO ) ) {
			return;
		}
		ent->name = (u32)(s32)ent->def->nameString | 0x10000;
	}
	if ( ent->info & ENT_IN_RING ) {
		Dbg_printf( "activate: already active" );
		return;
	}
	if ( m->nextOnList ) {
		Game_checkInactive( self, ent );
		if ( ent == self->inactiveMonsters && m->nextOnList == ent ) {
			self->inactiveMonsters = NULL;
		} else {
			if ( ent == self->inactiveMonsters ) {
				self->inactiveMonsters = m->nextOnList;
			}
			m->nextOnList->monster->prevOnList = m->prevOnList;
			m->prevOnList->monster->nextOnList = m->nextOnList;
		}
	}
	if ( !self->activeMonsters ) {
		m->nextOnList = m->prevOnList = ent;
		self->activeMonsters = ent;
	} else {
		Entity *first = self->activeMonsters;
		m->prevOnList = first->monster->prevOnList;
		m->nextOnList = first;
		first->monster->prevOnList->monster->nextOnList = ent;
		first->monster->prevOnList = ent;
	}
	ent->info |= ENT_IN_RING;
	m->ce.x = m->destX;
	m->ce.y = m->destY;
	if ( alert && ( m->flags & 0x10 ) ) {
		Game_executeTile( self, m->destX >> 6, m->destY >> 6, 0xf000, 0 );
		m->flags &= ~0x10;
	}
	if ( !Player_isVisible( self->player ) || !EntityMonster_getSound( m, 1 ) ) {
		return;
	}
	if ( self->alertMonster && !( ( App_random64( self->app ) >> 32 ) & 1 ) ) {
		return;
	}
	self->alertMonster = ent;
}

/* 0x0202fb5c (0x160 bytes) Game_deactivate (Ghidra: Game_FUN_0202fb5c)
 * file: name */
/* A monster back onto the inactive ring */
void Game_deactivate( Game *self, Entity *ent ) {
	Monster *m = ent->monster;

	if ( !m ) {
		App_fatal( app, "deactivate: NULL monster" );
		return;
	}
	if ( !ent->def ) {
		App_fatal( app, "deactivate: NULL entity def" );
		return;
	}
	if ( ent->def->eType != ETYPE_MONSTER ) {
		App_fatal( app, "deactivate: non-monster type (%d)", ent->def->eType );
		return;
	}
	if ( !( ent->info & ENT_IN_RING ) ) {
		Dbg_printf( "deactivate: already inactive" );
		return;
	}
	if ( m->nextOnList ) {
		Game_checkActive( self, ent );
		if ( ent == self->activeMonsters && m->nextOnList == ent ) {
			self->activeMonsters = NULL;
		} else {
			if ( ent == self->activeMonsters ) {
				self->activeMonsters = m->nextOnList;
			}
			m->nextOnList->monster->prevOnList = m->prevOnList;
			m->prevOnList->monster->nextOnList = m->nextOnList;
		}
	}
	if ( !self->inactiveMonsters ) {
		m->nextOnList = m->prevOnList = ent;
		self->inactiveMonsters = ent;
	} else {
		Entity *first = self->inactiveMonsters;
		m->prevOnList = first->monster->prevOnList;
		m->nextOnList = first;
		first->monster->prevOnList->monster->nextOnList = ent;
		first->monster->prevOnList = ent;
	}
	ent->info &= ~( ENT_IN_RING | ENT_LERPING );
}

