/* A door (line) opens or closes: op 0x0f open, 0x10 close, else toggle. Locked doors (0x400) do
 * not move. The door's entity leaves its tile while open; sound 0x39 opening, 0x36 closing. With
 * animate, a game sprite slides the door's picture one tile along x (line flag 0x100) or y (0x200)
 * in 250 ms; a door already sliding turns round. Returns 0 if nothing happened. */
int Game_useDoor( Game *self, int op, int line, int animate ) {
	Line		*l = &self->render->lines[line];
	Entity		*door = NULL;
	GameSprite	*gs = NULL;
	int			i;

	if ( l->flags & 0x400 ) {
		return 0;
	}
	if ( ( op == 0x0f && ( l->flags & 0x40 ) ) || ( op == 0x10 && !( l->flags & 0x40 ) ) ) {
		return 0;
	}
	l->flags ^= 0x40;
	for ( i = self->firstLineEntity; i <= self->lastLineEntity; i++ ) {
		door = &self->entities[i];		/* (with no match: the last one, for the sound) */
		if ( (int)( door->info & ENT_SPRITE_MASK ) - 1 == line ) {
			if ( !( l->flags & 0x40 ) ) {
				Game_linkEntity( self, door, door->tile % MAP_TILES, door->tile / MAP_TILES );
			} else {
				Game_unlinkEntity( self, door );
			}
			break;
		}
	}
	Sound_play( self->app->sound, door, ( l->flags & 0x40 ) ? 0x39 : 0x36, 0, 3 );
	if ( op == 0x0f ) {
		l->flags |= 0x40000;			/* opened once */
	}
	if ( !animate ) {
		return 1;
	}

	for ( i = 0; i < MAX_GAME_SPRITES; i++ ) {
		if ( ( self->gsprites[i].flags & GS_INUSE ) && self->gsprites[i].line == l ) {
			gs = &self->gsprites[i];
			break;
		}
	}
	if ( gs ) {
		/* turn round where it is */
		int t;
		gs->vx = -gs->vx;
		gs->vy = -gs->vy;
		gs->vz = -gs->vz;
		t = gs->toX; gs->toX = gs->fromX; gs->fromX = t;
		t = gs->toY; gs->toY = gs->fromY; gs->fromY = t;
		t = gs->toZ; gs->toZ = gs->fromZ; gs->fromZ = t;
		gs->startTime = self->app->time * 2 - gs->startTime - gs->duration;
		gs->flags |= GS_MOVING;
		gs->state = op == 0x0f ? 1 : 2;
	} else {
		gs = Game_gspriteAlloc( self, 0, (s8)l->texture, 0 );
		gs->line = l;
		gs->sprite->info = ( gs->sprite->info | 0x404000 ) & 0xfff87fff;
		if ( l->flags & 0x100 ) {
			gs->sprite->info |= 0x8000;
		} else if ( l->flags & 0x200 ) {
			gs->sprite->info |= 0x40000;
		}
		gs->state = 1;
		gs->flags |= GS_MOVING;
		gs->time8 = 250;
		gs->duration = 250;
		gs->time10 = 250;
		gs->fromX = gs->toX = ( l->x1 + l->x2 ) >> 1;
		gs->fromY = gs->toY = ( l->y1 + l->y2 ) >> 1;
		gs->fromZ = gs->toZ = 0x20;
		if ( l->flags & 0x100 ) {
			gs->toX += 0x40;
			gs->vx = 64000 / gs->duration;
		} else if ( l->flags & 0x200 ) {
			gs->toY += 0x40;
			gs->vy = 64000 / gs->duration;
		}
		if ( op == 0x10 ) {
			int t;
			gs->vx = -gs->vx;
			gs->vy = -gs->vy;
			gs->vz = -gs->vz;
			t = gs->toX; gs->toX = gs->fromX; gs->fromX = t;
			t = gs->toY; gs->toY = gs->fromY; gs->fromY = t;
			t = gs->toZ; gs->toZ = gs->fromZ; gs->fromZ = t;
			gs->state = 2;
		}
		gs->sprite->x = (s16)gs->fromX;
		gs->sprite->y = (s16)gs->fromY;
		gs->sprite->z = (s16)gs->fromZ;
	}
	if ( gs->state == 2 ) {
		Render_relinkSpriteAt( self->render, gs->sprite, gs->toX, gs->toY );
		Automap_tileChanged( self->app->menuSystem, gs->toX >> 6, gs->toY >> 6 );
	} else {
		Render_relinkSpriteAt( self->render, gs->sprite, -1, -1 );
		Automap_tileChanged( self->app->menuSystem, gs->fromX >> 6, gs->fromY >> 6 );
	}
	return 1;
}

