/* Monsters may be put where they are going unless one is still moving (ENT_LERPING) */
int Game_canSnapMonsters( Game *self ) {
	Entity *e;

	if ( self->forceSnap ) {
		return 1;
	}
	if ( ( e = self->activeMonsters ) != NULL ) {
		do {
			if ( e->info & ENT_LERPING ) {
				return 0;
			}
			e = e->monster->nextOnList;
		} while ( e != self->activeMonsters );
	}
	return 1;
}

