/* Each frame: the waiting threads whose time has come run on; those done are freed */
void Game_runScriptThreads( Game *self ) {
	int i, n;

	if ( self->numThreads == 0 ) {
		return;
	}
	for ( i = 0; i < MAX_SCRIPT_THREADS; i++ ) {
		ScriptThread *t = &self->threads[i];
		if ( !t->inUse ) {
			continue;
		}
		ScriptThread_checkWait( t, self->app->time );
		if ( t->state != SCRIPT_PAUSED || t->numFrames == 0 ) {
			Game_freeScriptThread( self, t );
		}
	}
	for ( i = n = 0; i < MAX_SCRIPT_THREADS; i++ ) {
		if ( self->threads[i].inUse ) {
			n++;
		}
	}
	if ( n != self->numThreads ) {
		OS_DebugBreak();
	}
}

