ScriptThread *Game_allocScriptThread( Game *self ) {
	int i;

	for ( i = 0; i < MAX_SCRIPT_THREADS; i++ ) {
		ScriptThread *t = &self->threads[i];
		if ( !t->inUse ) {
			ScriptThread_init( t );
			t->inUse = 1;
			t->id = (s8)i;
			self->numThreads++;
			Dbg_printf( "allocThread: %d", self->numThreads );
			return t;
		}
	}
	App_fatal( app, "MAX_SCRIPT_THREADS" );
	return NULL;
}

